css:
.corridor-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #2a2520;
    background: linear-gradient(168deg, #f4efe7 0%, #efe7da 55%, #e9ddcb 100%);
    border-radius: 18px;
}

.corridor-container * {
    box-sizing: border-box;
}

.corridor-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #25323b 0%, #34474f 50%, #7a4a2b 130%);
    color: #f7f1e8;
    border-radius: 16px;
    margin-bottom: 18px;
    box-shadow: 0 14px 34px rgba(37, 50, 59, 0.32);
}

.corridor-header h1 {
    margin: 10px 0 10px;
    font-size: 2.4rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.corridor-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.1px;
    font-weight: 700;
    color: #f0c08a;
    background: rgba(240, 192, 138, 0.13);
    border: 1px solid rgba(240, 192, 138, 0.40);
    padding: 5px 14px;
    border-radius: 999px;
}

.corridor-subtitle {
    margin: 0 auto;
    max-width: 840px;
    font-size: 1rem;
    line-height: 1.55;
    color: #ddd2c2;
}

.corridor-projects {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 12px;
    margin-bottom: 18px;
}

.corridor-project {
    background: #ffffff;
    border-radius: 14px;
    padding: 14px 18px;
    box-shadow: 0 4px 14px rgba(42, 37, 32, 0.08);
    display: flex;
    flex-direction: column;
    gap: 4px;
    border-left: 5px solid #7a4a2b;
}

.corridor-project-road { border-left-color: #c2521f; }
.corridor-project-transit { border-left-color: #2f7d8a; }
.corridor-project-bridge { border-left-color: #3f8f5b; }
.corridor-project-terminal { border-left-color: #b5892a; }

.corridor-project-name {
    font-weight: 800;
    font-size: 1.02rem;
    color: #2a2520;
}

.corridor-project-road .corridor-project-name { color: #b5491b; }
.corridor-project-transit .corridor-project-name { color: #266876; }
.corridor-project-bridge .corridor-project-name { color: #347a4d; }
.corridor-project-terminal .corridor-project-name { color: #9a7322; }

.corridor-project-meta {
    font-size: 0.82rem;
    color: #6b6258;
    line-height: 1.42;
}

.corridor-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #574d42;
    margin-bottom: 16px;
    padding: 4px 4px;
}

.corridor-period-counter #currentDay,
.corridor-period-counter #maxPeriods {
    font-weight: 800;
    color: #c2521f;
}

.corridor-round-name {
    background: rgba(194, 82, 31, 0.13);
    color: #b5491b;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.corridor-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #266876;
    background: rgba(47, 125, 138, 0.13);
    border: 1px solid rgba(47, 125, 138, 0.32);
    padding: 4px 12px;
    border-radius: 999px;
}

.corridor-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.corridor-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    box-shadow: 0 6px 16px rgba(42, 37, 32, 0.08);
    border-top: 4px solid #34474f;
}

.corridor-card-social { border-top-color: #3f8f5b; }
.corridor-card-budget { border-top-color: #266876; }
.corridor-card-exposure { border-top-color: #b5892a; }
.corridor-card-renego { border-top-color: #c2521f; }

.corridor-label {
    font-size: 0.73rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #7d7264;
}

.corridor-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #2a2520;
    font-variant-numeric: tabular-nums;
}

.corridor-card-social .corridor-value { color: #347a4d; }
.corridor-card-budget .corridor-value { color: #266876; }
.corridor-card-exposure .corridor-value { color: #9a7322; }
.corridor-card-renego .corridor-value { color: #c2521f; }

.corridor-sublabel {
    font-size: 0.75rem;
    color: #8a7f70;
    line-height: 1.35;
}

.corridor-card-budget.corridor-over .corridor-value { color: #c2331f; }
.corridor-card-budget.corridor-over { border-top-color: #c2331f; }
.corridor-card-exposure.corridor-exposure-high .corridor-value { color: #c2331f; }
.corridor-card-exposure.corridor-exposure-high { border-top-color: #c2331f; }
.corridor-card-social.corridor-social-good .corridor-value { color: #2e7d46; }

.corridor-credibility-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #ffffff;
    border: 1px solid #e3d8c7;
    color: #574d42;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.corridor-credibility-bar #credibilityDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #c2521f;
    font-weight: 800;
}

.corridor-credibility-bar.corridor-cred-high #credibilityDisplay { color: #2e7d46; }
.corridor-credibility-bar.corridor-cred-mid #credibilityDisplay { color: #9a7322; }

.corridor-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #c2521f;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(42, 37, 32, 0.07);
}

.corridor-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.corridor-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #34474f;
    margin-bottom: 6px;
}

.corridor-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #4a4036;
}

.corridor-briefing-text strong { color: #b5491b; }
.corridor-briefing-text em { color: #266876; font-style: italic; }

.corridor-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(42, 37, 32, 0.07);
}

.corridor-controls h3 {
    margin: 0 0 14px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #34474f;
    border-bottom: 2px solid #ece3d6;
    padding-bottom: 8px;
}

.corridor-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #3a3128;
    margin: 14px 0 6px;
}

.corridor-budget-note {
    font-size: 0.88rem;
    color: #574d42;
    background: #f7f1e7;
    border: 1px solid #e8dcc8;
    border-radius: 10px;
    padding: 10px 14px;
    margin: 0 0 6px;
    line-height: 1.5;
}

.corridor-budget-note strong { color: #b5491b; }

.corridor-container select,
.corridor-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #d6c9b4;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fffdf9;
    color: #2a2520;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.corridor-container select:focus,
.corridor-container input[type="number"]:focus {
    outline: none;
    border-color: #c2521f;
    box-shadow: 0 0 0 3px rgba(194, 82, 31, 0.16);
}

.corridor-container select option {
    background-color: #fffdf9;
    color: #2a2520;
}

.corridor-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #c2521f;
}

.corridor-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #574d42;
    margin-top: 4px;
}

.corridor-range-readout span:nth-child(2) {
    color: #c2521f;
    font-weight: 800;
}

.corridor-hint {
    font-size: 0.8rem;
    color: #8a7f70;
    margin-top: 6px;
    line-height: 1.42;
    font-style: italic;
}

.corridor-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.corridor-container .btn-primary {
    background: linear-gradient(135deg, #c2521f 0%, #a8421a 100%);
    border: none;
    color: #ffffff;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(168, 66, 26, 0.32);
}

.corridor-container .btn-primary:hover {
    filter: brightness(1.07);
}

.corridor-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #d6c9b4;
    color: #6b6258;
    background: transparent;
}

.corridor-coach {
    background: linear-gradient(160deg, #25323b 0%, #2f4049 100%);
    color: #e6ddcf;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 20px rgba(37, 50, 59, 0.26);
}

.corridor-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #f0c08a;
    margin-bottom: 8px;
}

.corridor-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.corridor-coach-body strong { color: #8fd6b0; }
.corridor-coach-body em { color: #f0c08a; font-style: italic; }

.corridor-history,
.corridor-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(42, 37, 32, 0.07);
}

.corridor-history h3,
.corridor-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #34474f;
}

.corridor-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #4a4036;
}

.corridor-container table#usfHistoryTable th {
    background: #f3ece0;
    color: #b5491b;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #e3d6c2;
}

.corridor-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #f0e9dd;
    color: #4a4036;
}

.corridor-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf6ee;
}

.corridor-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .corridor-container {
        padding: 14px;
    }
    .corridor-header h1 {
        font-size: 1.7rem;
    }
    .corridor-projects {
        grid-template-columns: 1fr;
    }
    .corridor-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .corridor-value {
        font-size: 1.9rem;
    }
    .corridor-clock {
        margin-left: 0;
    }
    .corridor-period-counter {
        font-size: 0.88rem;
    }
    .corridor-credibility-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .corridor-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ===== v1.1.0 completion debrief (append-only, corridor-cm-*) ===== */
.corridor-cm { color: #2a2520; font-family: inherit; }
.corridor-cm-generic { font-size: 15px; text-align: center; }
.corridor-cm-scoreband { text-align: center; padding: 6px 0 14px; border-bottom: 1px solid rgba(42,37,32,0.12); margin-bottom: 16px; }
.corridor-cm-score { font-size: 46px; font-weight: 700; line-height: 1; color: #3f8f5b; }
.corridor-cm-score-max { font-size: 20px; font-weight: 500; color: #8a7f70; margin-left: 2px; }
.corridor-cm-tier { font-size: 20px; font-weight: 600; margin-top: 6px; color: #2a2520; }
.corridor-cm-caption { font-size: 11.5px; letter-spacing: .05em; text-transform: uppercase; color: #8a7f70; margin-top: 4px; }
.corridor-cm-kpis { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin-bottom: 14px; }
.corridor-cm-kpi { flex: 1 1 96px; min-width: 96px; background: rgba(63,143,91,0.07); border: 1px solid rgba(63,143,91,0.18); border-radius: 10px; padding: 10px 8px; text-align: center; }
.corridor-cm-kpi-val { display: block; font-size: 21px; font-weight: 700; color: #2a2520; }
.corridor-cm-kpi-lbl { display: block; font-size: 11px; margin-top: 3px; color: #574d42; }
.corridor-cm-chips { display: flex; flex-wrap: wrap; gap: 8px; justify-content: center; margin-bottom: 14px; }
.corridor-cm-chip { font-size: 12.5px; font-weight: 600; padding: 5px 11px; border-radius: 999px; border: 1px solid transparent; }
.corridor-cm-chip.is-met { background: rgba(63,143,91,0.14); border-color: rgba(63,143,91,0.42); color: #2c6e43; }
.corridor-cm-chip.is-missed { background: rgba(194,82,31,0.12); border-color: rgba(194,82,31,0.4); color: #a5431a; }
.corridor-cm-insights { margin: 0; padding-left: 18px; }
.corridor-cm-insights li { font-size: 13.5px; line-height: 1.5; color: #3a332c; margin-bottom: 7px; }

