(function() {
    'use strict';

    class BuildCorridorAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Build the Corridor`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (ARIC — central corridor, Peru). All S/ millions.
            this.BUDGET = 2400;          // fixed co-financing envelope this cycle
            this.HURDLE = 10.5;          // private-capital hurdle rate (%)

            // Four competing projects. request/partial in S/ M; err = social ERR %; irr = investor IRR %;
            // add = additionality (1 = subsidy genuinely changes the outcome; 0 = private would build anyway).
            this.PROJECTS = {
                road:     { req: 1800, irr: 14.2, err: 12, add: 0.15, social: 12 },  // flagship, inflated forecast, lowest additionality
                transit:  { req: 1300, irr: 10.8, err: 16, add: 0.70, social: 16 },
                bridge:   { req: 1200, irr: 8.1,  err: 22, add: 1.00, social: 22 },  // highest social return, isolated province, needs subsidy
                terminal: { req: 800,  irr: 12.1, err: 11, add: 0.45, social: 11 }
            };
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    social: 0,            // social value delivered (0–100)
                    budget: 0,            // S/ M committed against the 2,400M envelope
                    exposure: 0,          // S/ M present-value contingent liability (guarantees)
                    renego: 70,           // renegotiation-risk index 0–100 (lower safer)
                    credibility: 45,      // ARIC regulatory credibility 0–100 (higher better)
                    // sticky run-defining penalty flags
                    forecastInflated: false,   // regulated on the +30% sponsor forecast
                    uncappedGuarantee: false,  // wrote the Treasury a blank cheque
                    bridgeStarved: false,      // deferred/rejected the highest-social project
                    thinSpread: false,         // funded all four below viability
                    tariffHurdleOnly: false,   // priced purely to the hurdle, usage collapsed
                    overBudget: false,         // allocation exceeded the envelope
                    fundingShare: {},          // per-project funded fraction
                    socialHistory: [0],
                    exposureHistory: [0],
                    renegoHistory: [70],
                    credibilityHistory: [45],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the classic errors — a blind click-through must NOT win:
                // rank by bankability, accept the inflated forecast, fund the two highest-IRR projects
                // (road + terminal) full, defer the social bridge, uncapped guarantees, tariff to the hurdle.
                state.decisions = {
                    rankBasis: `bankability`,
                    forecast: `sponsor`,
                    additionality: `bankable`,
                    scrutiny: 30,
                    fundRoad: `full`,
                    fundTransit: `defer`,
                    fundBridge: `defer`,
                    fundTerminal: `full`,
                    length: 20,
                    tariff: `hurdle`,
                    risk: `investor`,
                    mrg: `uncapped`,
                    indexation: `traffic`,
                    memo: `investment`,
                    defend: `leverage`,
                    kpi: `irr`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const rb = document.getElementById(`rankBasisInput`);
                const fc = document.getElementById(`forecastInput`);
                const ad = document.getElementById(`additionalityInput`);
                const sc = document.getElementById(`scrutinyInput`);
                if (rb) decisions.rankBasis = rb.value;
                if (fc) decisions.forecast = fc.value;
                if (ad) decisions.additionality = ad.value;
                if (sc) decisions.scrutiny = parseInt(sc.value, 10);
                if (!Number.isFinite(decisions.scrutiny) || decisions.scrutiny < 0 || decisions.scrutiny > 100) {
                    warn(`warn_scrutiny_range`); return false;
                }
            } else if (round === 2) {
                const fr = document.getElementById(`fundRoadInput`);
                const ft = document.getElementById(`fundTransitInput`);
                const fb = document.getElementById(`fundBridgeInput`);
                const fm = document.getElementById(`fundTerminalInput`);
                if (fr) decisions.fundRoad = fr.value;
                if (ft) decisions.fundTransit = ft.value;
                if (fb) decisions.fundBridge = fb.value;
                if (fm) decisions.fundTerminal = fm.value;
                const total = this._allocTotal(decisions);
                if (!Number.isFinite(total)) { warn(`warn_alloc`); return false; }
                if (total > this.BUDGET) { warn(`warn_over_budget`); return false; }
            } else if (round === 3) {
                const ln = document.getElementById(`lengthInput`);
                const ta = document.getElementById(`tariffInput`);
                const rk = document.getElementById(`riskInput`);
                const mg = document.getElementById(`mrgInput`);
                const ix = document.getElementById(`indexationInput`);
                if (ln) decisions.length = parseInt(ln.value, 10);
                if (ta) decisions.tariff = ta.value;
                if (rk) decisions.risk = rk.value;
                if (mg) decisions.mrg = mg.value;
                if (ix) decisions.indexation = ix.value;
                if (!Number.isFinite(decisions.length) || decisions.length < 15 || decisions.length > 30) {
                    warn(`warn_length_range`); return false;
                }
            } else if (round === 4) {
                const me = document.getElementById(`memoInput`);
                const df = document.getElementById(`defendInput`);
                const kp = document.getElementById(`kpiInput`);
                const cv = document.getElementById(`convictionInput`);
                if (me) decisions.memo = me.value;
                if (df) decisions.defend = df.value;
                if (kp) decisions.kpi = kp.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            this._updateBriefing(state);
            return true;
        }

        _fundFraction(level) {
            if (level === `full`) return 1;
            if (level === `partial`) return 0.5;
            return 0; // defer / reject
        }

        _allocTotal(d) {
            return Math.round(
                this.PROJECTS.road.req * this._fundFraction(d.fundRoad) +
                this.PROJECTS.transit.req * this._fundFraction(d.fundTransit) +
                this.PROJECTS.bridge.req * this._fundFraction(d.fundBridge) +
                this.PROJECTS.terminal.req * this._fundFraction(d.fundTerminal)
            );
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let socialDelta = 0, exposureDelta = 0, renegoDelta = 0, credDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Appraise and rank: separate social value from bankability; scrutinize the forecast.
                switch (d.rankBasis) {
                    case `social`: socialDelta += 10; credDelta += 6; renegoDelta -= 4; coachKey = `coach_r1_social`; break;
                    case `bankability`: socialDelta -= 2; renegoDelta += 4; credDelta -= 4; coachKey = `coach_r1_bankability`; break;
                    case `cost`: socialDelta += 1; renegoDelta += 2; coachKey = `coach_r1_cost`; break;
                }

                switch (d.forecast) {
                    case `independent`: renegoDelta -= 16; credDelta += 10; coachKey = `coach_r1_independent`; break;
                    case `sponsor`: ds.forecastInflated = true; renegoDelta += 20; credDelta -= 10; coachKey = `coach_r1_sponsor`; break;
                    case `average`: ds.forecastInflated = true; renegoDelta += 9; credDelta -= 3; coachKey = `coach_r1_average`; break;
                }

                switch (d.additionality) {
                    case `marginal`: socialDelta += 8; credDelta += 6; coachKey = `coach_r1_additionality`; break;
                    case `bankable`: socialDelta -= 4; credDelta -= 5; break;
                    case `all`: socialDelta -= 1; credDelta -= 1; break;
                }

                // Forecast scrutiny — auditing the demand studies lowers renegotiation risk.
                if (d.scrutiny >= 60) { renegoDelta -= 8; credDelta += 4; }
                else if (d.scrutiny <= 20) { renegoDelta += 6; credDelta -= 3; }

                summaryKey = (d.rankBasis === `social` && d.forecast === `independent` && d.additionality === `marginal`) ? `sum_r1_good` : `sum_r1_weak`;

            } else if (round === 2) {
                // Allocate the fixed budget. Compute the funded portfolio.
                const shares = {
                    road: this._fundFraction(d.fundRoad),
                    transit: this._fundFraction(d.fundTransit),
                    bridge: this._fundFraction(d.fundBridge),
                    terminal: this._fundFraction(d.fundTerminal)
                };
                ds.fundingShare = shares;
                ds.budget = this._allocTotal(d);

                // Over budget should never reach here (validation blocks it), but guard anyway.
                if (ds.budget > this.BUDGET) { ds.overBudget = true; renegoDelta += 10; credDelta -= 10; }
                else { ds.overBudget = false; }

                // Social value delivered: each funded project contributes ERR × additionality × funded fraction.
                // Additionality discount means funding the bankable road buys little genuine social value.
                let socialRaw = 0;
                for (const k in this.PROJECTS) {
                    const p = this.PROJECTS[k];
                    socialRaw += p.social * p.add * shares[k];
                }
                // Normalize to roughly 0–60 of the social KPI from the allocation itself.
                socialDelta += socialRaw * 1.6;

                // Bridge is the highest-social, isolated-province project; defer/reject = additionality failure.
                if (shares.bridge <= 0) {
                    ds.bridgeStarved = true;
                    socialDelta -= 18;
                    credDelta -= 12;
                    coachKey = `coach_r2_bridgestarved`;
                } else if (shares.bridge >= 1) {
                    credDelta += 6;
                }

                // Funding the road full while starving the bridge = the headline anti-pattern (decision tree #1).
                if (shares.road >= 1 && shares.bridge <= 0) {
                    credDelta -= 6;
                    coachKey = `coach_r2_bankableonly`;
                }

                // Thin even spread: slicing the envelope across many projects partial = several fall below
                // their viability threshold and none reaches financial close (decision tree #5). Funding ALL FOUR
                // partial costs S/ 2,550M (over the envelope, so it is blocked at validation); the reachable
                // form of the error is three-or-more projects funded partial — the budget is sliced thin.
                const partialCount = [d.fundRoad, d.fundTransit, d.fundBridge, d.fundTerminal].filter((v) => v === `partial`).length;
                const allPartial = partialCount >= 3;
                if (allPartial) {
                    ds.thinSpread = true;
                    socialDelta -= 16;
                    renegoDelta += 10;
                    credDelta -= 10;
                    coachKey = `coach_r2_thinspread`;
                }

                // Unspent envelope discipline: leaving room is fine; the win is the right portfolio, not max spend.
                if (!ds.bridgeStarved && !ds.thinSpread && shares.bridge >= 1 && (shares.transit > 0 || shares.terminal > 0)) {
                    coachKey = `coach_r2_disciplined`;
                    credDelta += 4;
                }

                summaryKey = ds.bridgeStarved ? `sum_r2_bridgestarved` :
                             ds.thinSpread ? `sum_r2_thinspread` :
                             (shares.bridge >= 1 ? `sum_r2_good` : `sum_r2_weak`);

            } else if (round === 3) {
                // Structure concession & tariff for the funded projects.
                // Concession length: longer spreads cost (lower tariff) but widens the demand-risk window.
                if (d.length >= 28) { renegoDelta += 6; socialDelta += 2; coachKey = `coach_r3_longplaza`; }
                else if (d.length <= 16) { socialDelta -= 3; renegoDelta -= 2; }
                else { renegoDelta -= 2; }

                // Tariff level — usage and legitimacy, not just cash flow (decision tree #4).
                switch (d.tariff) {
                    case `balanced`: socialDelta += 8; credDelta += 6; renegoDelta -= 4; break;
                    case `hurdle`: ds.tariffHurdleOnly = true; socialDelta -= 12; credDelta -= 6; renegoDelta += 6; coachKey = `coach_r3_hurdle`; break;
                    case `low`: socialDelta -= 4; renegoDelta += 4; coachKey = `coach_r3_lowtariff`; break;
                }

                // Risk allocation — assign each risk to the party best able to bear it.
                switch (d.risk) {
                    case `shared`: renegoDelta -= 12; credDelta += 8; break;
                    case `investor`: renegoDelta += 4; socialDelta -= 2; coachKey = (coachKey === `coach_default`) ? `coach_r3_riskinvestor` : coachKey; break;
                    case `state`: exposureDelta += 220; renegoDelta += 6; credDelta -= 6; break;
                }

                // Minimum-revenue guarantees — value and cap, or write a blank cheque (decision tree #3).
                switch (d.mrg) {
                    case `capped`:
                        exposureDelta += 180; renegoDelta -= 6; credDelta += 8;
                        // A capped, priced guarantee is what makes the isolated-province bridge investable
                        // without overpaying — additionality done right.
                        if (ds.fundingShare && ds.fundingShare.bridge > 0) { socialDelta += 6; coachKey = `coach_r3_capped`; }
                        break;
                    case `uncapped`:
                        ds.uncappedGuarantee = true;
                        exposureDelta += 640; renegoDelta += 14; credDelta -= 14;
                        coachKey = `coach_r3_uncapped`;
                        break;
                    case `none`:
                        // No exposure, but the sub-hurdle bridge may not reach close without support.
                        if (ds.fundingShare && ds.fundingShare.bridge > 0) { socialDelta -= 8; renegoDelta += 4; coachKey = `coach_r3_nomrg`; }
                        else { credDelta += 2; }
                        break;
                }

                // Indexation rule — tying tariff to the optimistic forecast bakes in renegotiation.
                switch (d.indexation) {
                    case `cpi`: renegoDelta -= 8; credDelta += 6; break;
                    case `traffic`: ds.forecastInflated = true; renegoDelta += 12; credDelta -= 8; coachKey = (coachKey === `coach_default`) ? `coach_r3_indextraffic` : coachKey; break;
                    case `none`: renegoDelta += 2; break;
                }

                const cleanStructure = (d.tariff === `balanced` && d.risk === `shared` && d.mrg === `capped` && d.indexation === `cpi`);
                if (cleanStructure) { coachKey = `coach_r3_clean`; }

                summaryKey = ds.uncappedGuarantee ? `sum_r3_uncapped` :
                             ds.tariffHurdleOnly ? `sum_r3_hurdle` :
                             cleanStructure ? `sum_r3_good` : `sum_r3_weak`;

            } else if (round === 4) {
                // Defend the decision before the lender and the finance minister.
                switch (d.memo) {
                    case `balanced`: socialDelta += 4; credDelta += 8; renegoDelta -= 4; coachKey = `coach_r4_balanced`; break;
                    case `investment`: credDelta -= 6; renegoDelta += 4; coachKey = `coach_r4_investment`; break;
                    case `harmony`: credDelta -= 3; socialDelta -= 2; coachKey = `coach_r4_harmony`; break;
                }

                switch (d.defend) {
                    case `additionality`: credDelta += 8; socialDelta += 3; if (d.memo === `balanced`) coachKey = `coach_r4_additionality`; break;
                    case `leverage`: credDelta -= 6; coachKey = `coach_r4_leverage`; break;
                    case `blameforecast`: credDelta -= 9; renegoDelta += 4; coachKey = `coach_r4_blame`; break;
                }

                switch (d.kpi) {
                    case `renego`: credDelta += 7; renegoDelta -= 6; break;
                    case `irr`: credDelta -= 4; renegoDelta += 3; break;
                    case `closings`: credDelta -= 2; break;
                }

                if (d.conviction >= 60) { credDelta += 4; renegoDelta -= 3; }
                else if (d.conviction <= 25) { credDelta -= 3; renegoDelta += 3; }

                summaryKey = (d.memo === `balanced` && d.defend === `additionality` && d.kpi === `renego`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // ---- Apply deltas. ----
            ds.social = Math.max(0, Math.min(100, Math.round((ds.social + socialDelta) * 10) / 10));
            ds.exposure = Math.max(0, Math.round(ds.exposure + exposureDelta));
            ds.renego = Math.max(0, Math.min(100, Math.round(ds.renego + renegoDelta)));
            ds.credibility = Math.max(0, Math.min(100, Math.round(ds.credibility + credDelta)));

            // ---- Sticky penalty flags GATE the headline KPIs and CAP the score so a later good
            // round cannot wash out a run-defining error. ----
            if (ds.forecastInflated) {
                ds.renego = Math.max(ds.renego, 62);        // renegotiation cycle is baked in
                ds.credibility = Math.min(ds.credibility, 58);
            }
            if (ds.uncappedGuarantee) {
                ds.exposure = Math.max(ds.exposure, 600);   // blank-cheque PV (concept: up to S/ 600–700M)
                ds.credibility = Math.min(ds.credibility, 50);
            }
            if (ds.bridgeStarved) {
                ds.social = Math.min(ds.social, 46);        // additionality failure caps social value
                ds.credibility = Math.min(ds.credibility, 52);
            }
            if (ds.thinSpread) {
                ds.social = Math.min(ds.social, 42);        // nothing reaches financial close
                ds.renego = Math.max(ds.renego, 58);
            }
            if (ds.tariffHurdleOnly) {
                ds.social = Math.min(ds.social, 60);        // usage falls ~18%, social benefit erodes
            }
            if (ds.overBudget) {
                ds.credibility = Math.min(ds.credibility, 40);
            }

            ds.socialHistory.push(ds.social);
            ds.exposureHistory.push(ds.exposure);
            ds.renegoHistory.push(ds.renego);
            ds.credibilityHistory.push(ds.credibility);

            // ---- Persist composite where the grading/reporting layer reads it ----
            const _score = this._composite(ds);
            ds.score = _score;
            ds.performance = ds.performance || {};
            ds.performance.overallScore = _score;

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                overallScore: _score,
                score: _score,
                social: ds.social,
                socialDelta: Math.round(socialDelta * 10) / 10,
                budget: ds.budget,
                exposure: ds.exposure,
                renego: ds.renego,
                credibility: ds.credibility,
                forecastInflated: ds.forecastInflated,
                uncappedGuarantee: ds.uncappedGuarantee,
                bridgeStarved: ds.bridgeStarved,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _renegoLabel(v) {
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            if (v >= 55) return t(`renego_high`);
            if (v >= 30) return t(`renego_mid`);
            return t(`renego_low`);
        }

        _credLabel(v) {
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            if (v >= 70) return t(`cred_high`);
            if (v >= 50) return t(`cred_mid`);
            return t(`cred_low`);
        }

        _fmtMoney(v) {
            const n = Math.round(Number(v));
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const grouped = n.toString().replace(/\B(?=(\d{3})+(?!\d))/g, lang === `es` ? `,` : `,`);
            return `S/ ${grouped}M`;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`socialDisplay`, `domainState.social`, (v) => {
                const n = Math.round(Number(v));
                const card = document.querySelector(`.corridor-card-social`);
                if (card) card.classList.toggle(`corridor-social-good`, n >= 65);
                return `${n}`;
            });

            uiManager.bind(`budgetDisplay`, `domainState.budget`, (v) => {
                const card = document.querySelector(`.corridor-card-budget`);
                if (card) card.classList.toggle(`corridor-over`, Number(v) > self.BUDGET);
                return self._fmtMoney(v);
            });

            uiManager.bind(`exposureDisplay`, `domainState.exposure`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.corridor-card-exposure`);
                if (card) card.classList.toggle(`corridor-exposure-high`, n >= 500);
                return self._fmtMoney(v);
            });

            uiManager.bind(`renegoDisplay`, `domainState.renego`, (v) => self._renegoLabel(Number(v)));

            uiManager.bind(`credibilityDisplay`, `domainState.credibility`, (v) => {
                const n = Number(v);
                const bar = document.querySelector(`.corridor-credibility-bar`);
                if (bar) {
                    bar.classList.toggle(`corridor-cred-high`, n >= 70);
                    bar.classList.toggle(`corridor-cred-mid`, n >= 50 && n < 70);
                }
                return self._credLabel(n) + ` · ` + n;
            });

            // Scrutiny slider readout.
            const sc = document.getElementById(`scrutinyInput`);
            const scReadout = document.getElementById(`scrutinyReadout`);
            if (sc && scReadout) {
                scReadout.textContent = sc.value;
                sc.addEventListener(`input`, function() { scReadout.textContent = sc.value; });
            }
        }

        getChartConfig() {
            return {
                corridorChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(`chart_series_social`) : `Social value delivered (0–100)`,
                                data: [],
                                borderColor: `#3f8f5b`,
                                backgroundColor: `rgba(63,143,91,0.12)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#3f8f5b`,
                                yAxisID: `y`
                            },
                            {
                                label: (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(`chart_series_exposure`) : `Treasury exposure (S/ M)`,
                                data: [],
                                borderColor: `#b5892a`,
                                backgroundColor: `rgba(181,137,42,0.10)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#b5892a`,
                                yAxisID: `y1`
                            },
                            {
                                label: (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(`chart_series_renego`) : `Renegotiation risk (0–100)`,
                                data: [],
                                borderColor: `#c2521f`,
                                backgroundColor: `rgba(194,82,31,0.08)`,
                                borderWidth: 2,
                                borderDash: [5, 4],
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#c2521f`,
                                yAxisID: `y`
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { position: `bottom`, labels: { color: `#574d42`, boxWidth: 14 } },
                            title: { display: false }
                        },
                        scales: {
                            y: {
                                beginAtZero: true, max: 100, position: `left`,
                                ticks: { color: `#8a7f70` }, grid: { color: `rgba(42,37,32,0.06)` },
                                title: { display: true, text: `0–100`, color: `#8a7f70` }
                            },
                            y1: {
                                beginAtZero: true, position: `right`,
                                ticks: { color: `#b5892a` }, grid: { drawOnChartArea: false },
                                title: { display: true, text: `S/ M`, color: `#b5892a` }
                            },
                            x: {
                                ticks: { color: `#8a7f70` }, grid: { color: `rgba(42,37,32,0.04)` },
                                title: { display: true, text: `Round`, color: `#8a7f70` }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.socialHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                corridorChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.socialHistory.map((v) => Math.round(v)) },
                        { data: ds.exposureHistory.map((v) => Math.round(v)) },
                        { data: ds.renegoHistory.map((v) => Math.round(v)) }
                    ]
                }
            };
        }

        _composite(ds) {
            // v1.0.0 completion formula, single source of truth, persisted every period so the
            // grading/analytics/LTI layer (domainState.performance.overallScore then top-level
            // score) receives a number instead of null -> 0.0.
            const social = Math.round(ds.social);
            const exposure = Math.round(ds.exposure);
            const renego = Math.round(ds.renego);
            const credibility = Math.round(ds.credibility);
            const exposureScore = Math.max(0, 100 - (exposure / 7));
            const renegoScore = 100 - renego;
            return Math.round(social * 0.34 + credibility * 0.26 + renegoScore * 0.24 + exposureScore * 0.16);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const social = Math.round(ds.social);
            const exposure = Math.round(ds.exposure);
            const renego = Math.round(ds.renego);
            const credibility = Math.round(ds.credibility);

            // Composite: social value and credibility up, renegotiation risk and exposure down.
            const composite = this._composite(ds);

            const sociallyStrong = social >= 65;
            const lowRenego = renego <= 30;
            const exposureControlled = exposure <= 300;
            const credible = credibility >= 70;

            const anyFlag = ds.forecastInflated || ds.uncappedGuarantee || ds.bridgeStarved || ds.thinSpread || ds.overBudget;

            // Pattern label.
            let pattern = `mixed`;
            if (ds.bridgeStarved) pattern = `bankable`;
            else if (ds.forecastInflated) pattern = `forecast`;
            else if (ds.uncappedGuarantee) pattern = `guarantee`;
            else if (ds.thinSpread) pattern = `thin`;
            else if (ds.tariffHurdleOnly) pattern = `tariff`;
            else if (sociallyStrong && lowRenego && exposureControlled && credible) pattern = `catalysed`;

            // The headline anti-patterns CANNOT reach the top verdict (gated by sticky flags).
            let performance = `Renegotiation Cycle Repeated`, performanceKey = `grade_renego`;
            if (!anyFlag && sociallyStrong && lowRenego && exposureControlled && credible && composite >= 75) {
                performance = `Corridor Catalysed`; performanceKey = `grade_catalysed`;
            } else if (!ds.bridgeStarved && !ds.uncappedGuarantee && (sociallyStrong || lowRenego) && composite >= 60) {
                performance = `Sound but Incomplete`; performanceKey = `grade_sound`;
            } else if (ds.bridgeStarved) {
                performance = `Bankable-Only Trap`; performanceKey = `grade_bankable`;
            } else if (ds.uncappedGuarantee) {
                performance = `Treasury Blank Cheque`; performanceKey = `grade_guarantee`;
            } else if (ds.forecastInflated) {
                performance = `Renegotiation Cycle Repeated`; performanceKey = `grade_renego`;
            } else if (ds.thinSpread) {
                performance = `Spread Too Thin`; performanceKey = `grade_thin`;
            } else {
                performance = `Mixed Outcome`; performanceKey = `grade_mixed`;
            }

            const insights = [];
            if (performance === `Corridor Catalysed`) insights.push(window.mySimulation.t(`insight_catalysed`));
            else if (ds.bridgeStarved) insights.push(window.mySimulation.t(`insight_bankable`));
            else if (ds.forecastInflated) insights.push(window.mySimulation.t(`insight_forecast`));
            else if (ds.uncappedGuarantee) insights.push(window.mySimulation.t(`insight_guarantee`));
            else if (ds.thinSpread) insights.push(window.mySimulation.t(`insight_thin`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (ds.uncappedGuarantee) insights.push(window.mySimulation.t(`insight_exposure`));
            if (ds.tariffHurdleOnly) insights.push(window.mySimulation.t(`insight_tariff`));
            if (!credible) insights.push(window.mySimulation.t(`insight_credibility`));
            if (sociallyStrong && exposureControlled && lowRenego && !credible) insights.push(window.mySimulation.t(`insight_almost`));

            return {
                social: social,
                exposure: exposure,
                renego: renego,
                credibility: credibility,
                sociallyStrong: sociallyStrong,
                lowRenego: lowRenego,
                exposureControlled: exposureControlled,
                credible: credible,
                pattern: pattern,
                composite: composite,
                performance: performance,
                performanceKey: performanceKey,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const self = this;
            const t = (window.mySimulation && window.mySimulation.t)
                ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            if (!summary || typeof summary.composite !== `number`) {
                return `<div class="corridor-cm"><p class="corridor-cm-generic">${t(`cm_generic`)}</p></div>`;
            }
            const tier = summary.performanceKey ? t(summary.performanceKey) : (summary.performance || ``);
            const kpi = (labelKey, valStr) =>
                `<div class="corridor-cm-kpi"><span class="corridor-cm-kpi-val">${valStr}</span>`
                + `<span class="corridor-cm-kpi-lbl">${t(labelKey)}</span></div>`;
            const chip = (ok, labelKey) =>
                `<span class="corridor-cm-chip ${ok ? `is-met` : `is-missed`}">`
                + `${ok ? `✓` : `✗`} ${t(labelKey)}</span>`;
            const insights = (summary.insights || []).map((x) => `<li>${x}</li>`).join(``);
            return ``
                + `<div class="corridor-cm">`
                +   `<div class="corridor-cm-scoreband">`
                +     `<div class="corridor-cm-score">${summary.composite}<span class="corridor-cm-score-max">/100</span></div>`
                +     `<div class="corridor-cm-tier">${tier}</div>`
                +     `<div class="corridor-cm-caption">${t(`cm_caption`)}</div>`
                +   `</div>`
                +   `<div class="corridor-cm-kpis">`
                +     kpi(`cm_kpi_social`, String(Math.round(summary.social)))
                +     kpi(`cm_kpi_exposure`, self._fmtMoney(summary.exposure))
                +     kpi(`cm_kpi_renego`, String(Math.round(summary.renego)))
                +     kpi(`cm_kpi_credibility`, String(Math.round(summary.credibility)))
                +   `</div>`
                +   `<div class="corridor-cm-chips">`
                +     chip(summary.sociallyStrong, `cm_chip_social`)
                +     chip(summary.lowRenego, `cm_chip_renego`)
                +     chip(summary.exposureControlled, `cm_chip_exposure`)
                +     chip(summary.credible, `cm_chip_credible`)
                +   `</div>`
                +   (insights ? `<ul class="corridor-cm-insights">${insights}</ul>` : ``)
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.bridgeStarved) return window.mySimulation.t(`hint_bridge`);
            if (ds.uncappedGuarantee) return window.mySimulation.t(`hint_guarantee`);
            if (ds.forecastInflated && state.currentPeriod < 3) return window.mySimulation.t(`hint_forecast`);
            if (ds.renego >= 60) return window.mySimulation.t(`hint_renego`);
            if (ds.social < 40 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_social`);
            if (ds.social >= 65 && ds.renego <= 30 && ds.exposure <= 300) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            const self = this;
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.social`, label: `Social`, i18nKey: `col_social`, formatter: (v) => `${Math.round(v)}` },
                { key: `results.exposure`, label: `Exposure`, i18nKey: `col_exposure`, formatter: (v) => self._fmtMoney(v) },
                { key: `results.renego`, label: `Renego`, i18nKey: `col_renego`, formatter: (v) => `${Math.round(v)}` },
                { key: `results.credibility`, label: `Credibility`, i18nKey: `col_credibility`, formatter: (v) => `${Math.round(v)}` }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);

            for (let i = 0; i < this.ROUNDS.length; i++) {
                const panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? `block` : `none`;
            }
        }

